"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  type ChartStatus,
  ChartDataTable,
  ChartState,
  type Candle,
  DATE_SHORT,
  DOWN,
  EASE,
  Keyframes,
  MARKET_RANGES,
  type MarketRange,
  RangeSelector,
  SURFACE,
  UP,
  formatAxisPrice,
  formatMoney,
  formatSignedPct,
  monotonePath,
  niceTicks,
  useElementWidth,
  useHoverIndexKeys,
  usePrefersReducedMotion,
  useTween,
} from "@/components/moneytrees/charts/chart-engine";

export function rsi(closes: number[], period = 14): (number | null)[] {
  const out: (number | null)[] = Array.from({ length: closes.length }, () => null);
  if (closes.length <= period) return out;

  let gain = 0;
  let loss = 0;
  for (let i = 1; i <= period; i += 1) {
    const change = closes[i]! - closes[i - 1]!;
    if (change >= 0) gain += change;
    else loss -= change;
  }
  gain /= period;
  loss /= period;
  out[period] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);

  for (let i = period + 1; i < closes.length; i += 1) {
    const change = closes[i]! - closes[i - 1]!;
    gain = (gain * (period - 1) + Math.max(0, change)) / period;
    loss = (loss * (period - 1) + Math.max(0, -change)) / period;
    out[i] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
  }
  return out;
}

function ema(values: number[], period: number): number[] {
  const k = 2 / (period + 1);
  const out: number[] = [];
  let prev = values[0] ?? 0;
  for (let i = 0; i < values.length; i += 1) {
    prev = i === 0 ? values[0]! : values[i]! * k + prev * (1 - k);
    out.push(prev);
  }
  return out;
}

export function macd(closes: number[], fast = 12, slow = 26, signalPeriod = 9) {
  const fastEma = ema(closes, fast);
  const slowEma = ema(closes, slow);
  const line = closes.map((_, i) => fastEma[i]! - slowEma[i]!);
  const signal = ema(line, signalPeriod);
  return { line, signal, histogram: line.map((v, i) => v - signal[i]!) };
}

const PAD = { top: 12, right: 58, bottom: 22, left: 12 };
const GAP = 14;
const PANE_SHARE = { price: 0.54, rsi: 0.22, macd: 0.24 };

export interface IndicatorChartProps {
  className?: string;
  data: Candle[];
  symbol?: string;
  name?: string;
  ranges?: MarketRange[];
  defaultRange?: string;
  height?: number;
  status?: ChartStatus;
  onRetry?: () => void;
}

type MacdSeries = { line: number[]; signal: number[]; histogram: number[] };
type Scale = (v: number) => number;
type Point = { x: number; y: number };

function resolveRange(ranges: MarketRange[], label: string): MarketRange {
  return ranges.find((r) => r.label === label) ?? ranges[ranges.length - 1]!;
}

function viewStart(length: number, bars: number | null): number {
  if (bars == null || bars >= length) return 0;
  return length - bars;
}

function priceDomain(view: Candle[]): readonly [number, number] {
  if (!view.length) return [0, 1] as const;
  let lo = Infinity;
  let hi = -Infinity;
  for (const c of view) {
    if (c.low < lo) lo = c.low;
    if (c.high > hi) hi = c.high;
  }
  const pad = (hi - lo) * 0.1 || 1;
  return [lo - pad, hi + pad] as const;
}

function macdExtent(series: MacdSeries): number {
  let max = 1e-6;
  for (let i = 0; i < series.line.length; i += 1) {
    max = Math.max(
      max,
      Math.abs(series.line[i]!),
      Math.abs(series.signal[i]!),
      Math.abs(series.histogram[i]!),
    );
  }
  return max * 1.15;
}

function pickTimeTicks(n: number, plotW: number, cx: Scale): number[] {
  if (!n) return [];
  const want = Math.max(2, Math.min(6, Math.floor(plotW / 96)));
  const gap = Math.max(1, Math.floor((n - 1) / (want - 1 || 1)));
  const out: number[] = [];
  for (let i = 0; i < n; i += gap) out.push(i);
  const minGap = 62;
  if (out[out.length - 1] !== n - 1) {
    while (out.length && cx(n - 1) - cx(out[out.length - 1]!) < minGap) out.pop();
    out.push(n - 1);
  }
  return out;
}

function pctFrom(base: number, value: number): number {
  return base ? ((value - base) / base) * 100 : 0;
}

function dirInk(delta: number): string {
  return delta >= 0 ? UP : DOWN;
}

function rsiInk(value: number | null | undefined): string | undefined {
  if (value == null) return undefined;
  if (value >= 70) return DOWN;
  if (value <= 30) return UP;
  return undefined;
}

function fixedOrDash(value: number | null | undefined, digits: number): string {
  return value == null ? "—" : value.toFixed(digits);
}

function motionStyle(reduce: boolean, style: React.CSSProperties): React.CSSProperties | undefined {
  return reduce ? undefined : style;
}

function indicatorLayout(width: number, height: number, n: number) {
  const w = Math.max(width, 260);
  const x0 = PAD.left;
  const x1 = w - PAD.right;
  const plotW = Math.max(1, x1 - x0);
  const innerTop = PAD.top;
  const innerBottom = height - PAD.bottom;
  const usable = innerBottom - innerTop - GAP * 2;
  const priceTop = innerTop;
  const priceBottom = priceTop + usable * PANE_SHARE.price;
  const rsiTop = priceBottom + GAP;
  const rsiBottom = rsiTop + usable * PANE_SHARE.rsi;
  const macdTop = rsiBottom + GAP;
  const macdBottom = macdTop + usable * PANE_SHARE.macd;
  const step = plotW / Math.max(n, 1);
  const barW = Math.max(1, Math.min(step * 0.62, 12));
  return {
    w,
    h: height,
    x0,
    x1,
    plotW,
    innerBottom,
    priceTop,
    priceBottom,
    rsiTop,
    rsiBottom,
    macdTop,
    macdBottom,
    macdZero: (macdTop + macdBottom) / 2,
    step,
    barW,
  };
}

type Layout = ReturnType<typeof indicatorLayout>;

function useIndicatorSeries(data: Candle[], range: MarketRange) {
  const closesAll = React.useMemo(() => data.map((c) => c.close), [data]);
  const rsiAll = React.useMemo(() => rsi(closesAll), [closesAll]);
  const macdAll = React.useMemo(() => macd(closesAll), [closesAll]);
  const start = React.useMemo(() => viewStart(data.length, range.bars), [data.length, range.bars]);
  const view = React.useMemo(() => data.slice(start), [data, start]);
  const rsiView = React.useMemo(() => rsiAll.slice(start), [rsiAll, start]);
  const macdView = React.useMemo<MacdSeries>(
    () => ({
      line: macdAll.line.slice(start),
      signal: macdAll.signal.slice(start),
      histogram: macdAll.histogram.slice(start),
    }),
    [macdAll, start],
  );
  return { view, rsiView, macdView };
}

function useIndicatorScales(view: Candle[], macdView: MacdSeries, layout: Layout, reduce: boolean) {
  const { x0, step, priceTop, priceBottom, rsiTop, rsiBottom, macdTop, macdBottom, macdZero } =
    layout;
  const cx = React.useCallback((i: number) => x0 + step * (i + 0.5), [x0, step]);
  const rawPriceDomain = React.useMemo(() => priceDomain(view), [view]);
  const [pLo = 0, pHi = 0] = useTween([rawPriceDomain[0], rawPriceDomain[1]], {
    duration: 520,
    enabled: !reduce,
  });
  const priceY = React.useCallback(
    (v: number) => priceBottom - ((v - pLo) / (pHi - pLo || 1)) * (priceBottom - priceTop),
    [pLo, pHi, priceBottom, priceTop],
  );
  const rsiY = React.useCallback(
    (v: number) => rsiBottom - (v / 100) * (rsiBottom - rsiTop),
    [rsiBottom, rsiTop],
  );
  const macdMax = React.useMemo(() => macdExtent(macdView), [macdView]);
  const macdY = React.useCallback(
    (v: number) => macdZero - (v / macdMax) * ((macdBottom - macdTop) / 2),
    [macdZero, macdMax, macdBottom, macdTop],
  );
  return { cx, priceY, rsiY, macdY, pLo, pHi };
}

function useIndicatorPaths(
  view: Candle[],
  rsiView: (number | null)[],
  macdView: MacdSeries,
  scales: { cx: Scale; priceY: Scale; rsiY: Scale; macdY: Scale },
) {
  const { cx, priceY, rsiY, macdY } = scales;
  const closeLine = React.useMemo(
    () => monotonePath(view.map((c, i) => ({ x: cx(i), y: priceY(c.close) }))),
    [view, cx, priceY],
  );
  const rsiLine = React.useMemo(() => {
    const points = rsiView
      .map((v, i) => (v == null ? null : { x: cx(i), y: rsiY(v) }))
      .filter((p): p is Point => p != null);
    return monotonePath(points);
  }, [rsiView, cx, rsiY]);
  const macdLine = React.useMemo(
    () => monotonePath(macdView.line.map((v, i) => ({ x: cx(i), y: macdY(v) }))),
    [macdView.line, cx, macdY],
  );
  const signalLine = React.useMemo(
    () => monotonePath(macdView.signal.map((v, i) => ({ x: cx(i), y: macdY(v) }))),
    [macdView.signal, cx, macdY],
  );
  return { closeLine, rsiLine, macdLine, signalLine };
}

function useIndicatorTicks(n: number, plotW: number, pLo: number, pHi: number, cx: Scale) {
  const priceTicks = React.useMemo(() => niceTicks(pLo, pHi, 4), [pLo, pHi]);
  const timeTicks = React.useMemo(() => pickTimeTicks(n, plotW, cx), [n, plotW, cx]);
  return { priceTicks, timeTicks };
}

function indicatorReadout(
  view: Candle[],
  rsiView: (number | null)[],
  macdView: MacdSeries,
  hoverIndex: number | null,
) {
  const n = view.length;
  const last = view[n - 1];
  const activeIndex = hoverIndex ?? n - 1;
  const active = view[activeIndex];
  const base = view[0]?.close ?? 0;
  const activeClose = active?.close ?? 0;
  const lastClose = last?.close ?? 0;
  return {
    last,
    active,
    activeClose,
    lastClose,
    activeRsi: rsiView[activeIndex],
    activeMacd: macdView.line[activeIndex],
    activeSignal: macdView.signal[activeIndex],
    delta: pctFrom(base, activeClose),
    rangeDelta: pctFrom(base, lastClose),
  };
}

type Readout = ReturnType<typeof indicatorReadout>;

function IndicatorReadout({
  symbol,
  name,
  readout,
}: {
  symbol: string;
  name: string;
  readout: Readout;
}) {
  const { active, activeClose, activeRsi, activeMacd, activeSignal, delta } = readout;
  return (
    <div>
      <div className="flex items-baseline gap-2">
        <span className="font-mono text-[12px] font-medium tracking-wide text-foreground">
          {symbol}
        </span>
        <span className="text-[12px] text-muted-foreground">{name}</span>
      </div>
      <div className="mt-1 flex items-end gap-2.5">
        <span className="font-mono text-[24px] font-medium leading-none tabular-nums text-foreground">
          {formatMoney(activeClose)}
        </span>
        <span
          className="mb-0.5 font-mono text-[12px] tabular-nums"
          style={{ color: dirInk(delta) }}
        >
          {formatSignedPct(delta)}
        </span>
      </div>
      <div className="mt-1.5 flex flex-wrap items-center gap-x-3 font-mono text-[10.5px] tabular-nums">
        <span className="text-muted-foreground/70">
          {active ? DATE_SHORT.format(active.t) : ""}
        </span>
        <span className="text-muted-foreground">
          RSI{" "}
          <span className="text-foreground" style={{ color: rsiInk(activeRsi) }}>
            {fixedOrDash(activeRsi, 1)}
          </span>
        </span>
        <span className="text-muted-foreground">
          MACD <span className="text-foreground">{fixedOrDash(activeMacd, 2)}</span>
        </span>
        <span className="text-muted-foreground">
          Signal <span className="text-foreground">{fixedOrDash(activeSignal, 2)}</span>
        </span>
      </div>
    </div>
  );
}

function PaneLabel({ x0, y, text }: { x0: number; y: number; text: string }) {
  return (
    <text
      x={x0 + 2}
      y={y + 10}
      fontSize={9.5}
      fontWeight={600}
      fill="currentColor"
      opacity={0.55}
      className="font-mono uppercase tracking-wider"
    >
      {text}
    </text>
  );
}

function PricePane({
  symbol,
  layout,
  n,
  cx,
  priceY,
  priceTicks,
  closeLine,
  last,
  dirColor,
  uid,
  introKey,
  reduce,
}: {
  symbol: string;
  layout: Layout;
  n: number;
  cx: Scale;
  priceY: Scale;
  priceTicks: number[];
  closeLine: string;
  last: Candle | undefined;
  dirColor: string;
  uid: string;
  introKey: string;
  reduce: boolean;
}) {
  const { x0, x1, priceTop, priceBottom } = layout;
  return (
    <>
      <g shapeRendering="crispEdges">
        {priceTicks.map((tick) => {
          const y = priceY(tick);
          if (y < priceTop - 1 || y > priceBottom + 1) return null;
          if (last && Math.abs(y - priceY(last.close)) < 13) return null;
          return (
            <line
              key={tick}
              x1={x0}
              x2={x1}
              y1={y}
              y2={y}
              stroke="currentColor"
              strokeOpacity={0.12}
              strokeDasharray="2 4"
            />
          );
        })}
      </g>
      <g className="font-mono">
        {priceTicks.map((tick) => {
          const y = priceY(tick);
          if (y < priceTop - 1 || y > priceBottom + 1) return null;
          if (last && Math.abs(y - priceY(last.close)) < 13) return null;
          return (
            <text
              key={tick}
              x={x1 + 8}
              y={y}
              dominantBaseline="middle"
              fontSize={10.5}
              fill="currentColor"
              className="tabular-nums"
            >
              {formatAxisPrice(tick)}
            </text>
          );
        })}
      </g>

      <g key={`${introKey}-price`}>
        <path
          d={`${closeLine}L${cx(n - 1)},${priceBottom}L${cx(0)},${priceBottom}Z`}
          fill={`url(#${uid}-price)`}
          style={motionStyle(reduce, { animation: `spectrum-mc-fade 560ms ease-out both` })}
        />
        <path
          d={closeLine}
          fill="none"
          stroke={dirColor}
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          pathLength={1}
          style={motionStyle(reduce, {
            strokeDasharray: 1,
            animation: `spectrum-mc-draw 880ms ${EASE} both`,
          })}
        />
      </g>
      <PaneLabel x0={x0} y={priceTop - 10} text={`${symbol} · close`} />

      {last ? (
        <g>
          <line
            x1={x0}
            x2={x1}
            y1={priceY(last.close)}
            y2={priceY(last.close)}
            stroke={dirColor}
            strokeOpacity={0.5}
            strokeDasharray="4 4"
          />
          <rect
            x={x1 + 3}
            y={priceY(last.close) - 9}
            width={PAD.right - 8}
            height={18}
            rx={4}
            fill={dirColor}
          />
          <text
            x={x1 + 3 + (PAD.right - 8) / 2}
            y={priceY(last.close)}
            textAnchor="middle"
            dominantBaseline="middle"
            fontSize={10.5}
            fontWeight={600}
            fill={SURFACE}
            className="font-mono tabular-nums"
          >
            {formatAxisPrice(last.close)}
          </text>
        </g>
      ) : null}
    </>
  );
}

function RsiPane({
  layout,
  rsiY,
  rsiLine,
  uid,
  introKey,
  reduce,
}: {
  layout: Layout;
  rsiY: Scale;
  rsiLine: string;
  uid: string;
  introKey: string;
  reduce: boolean;
}) {
  const { x0, x1, plotW, rsiTop } = layout;
  return (
    <>
      <g clipPath={`url(#${uid}-rsi)`}>
        <rect
          x={x0}
          y={rsiY(70)}
          width={plotW}
          height={Math.max(0, rsiY(30) - rsiY(70))}
          fill="currentColor"
          opacity={0.05}
        />
        {[30, 70].map((level) => (
          <line
            key={level}
            x1={x0}
            x2={x1}
            y1={rsiY(level)}
            y2={rsiY(level)}
            stroke={level === 70 ? DOWN : UP}
            strokeOpacity={0.45}
            strokeDasharray="3 3"
          />
        ))}
        <path
          key={`${introKey}-rsi`}
          d={rsiLine}
          fill="none"
          stroke="var(--spectrum-chart-4)"
          strokeWidth={1.6}
          strokeLinecap="round"
          pathLength={1}
          style={motionStyle(reduce, {
            strokeDasharray: 1,
            animation: `spectrum-mc-draw 880ms ${EASE} 120ms both`,
          })}
        />
      </g>
      <g className="font-mono">
        {[30, 70].map((level) => (
          <text
            key={level}
            x={x1 + 8}
            y={rsiY(level)}
            dominantBaseline="middle"
            fontSize={9.5}
            fill="currentColor"
            className="tabular-nums"
          >
            {level}
          </text>
        ))}
      </g>
      <PaneLabel x0={x0} y={rsiTop - 10} text="RSI 14" />
    </>
  );
}

function MacdPane({
  layout,
  n,
  cx,
  macdY,
  histogram,
  macdLine,
  signalLine,
  hoverIndex,
  introKey,
  reduce,
}: {
  layout: Layout;
  n: number;
  cx: Scale;
  macdY: Scale;
  histogram: number[];
  macdLine: string;
  signalLine: string;
  hoverIndex: number | null;
  introKey: string;
  reduce: boolean;
}) {
  const { x0, x1, macdTop, macdZero, barW } = layout;
  return (
    <>
      <g key={`${introKey}-macd`}>
        <line
          x1={x0}
          x2={x1}
          y1={macdZero}
          y2={macdZero}
          stroke="currentColor"
          strokeOpacity={0.2}
          shapeRendering="crispEdges"
        />
        {histogram.map((v, i) => {
          const y = macdY(v);
          const positive = v >= 0;
          return (
            <rect
              key={i}
              x={cx(i) - barW / 2}
              y={positive ? y : macdZero}
              width={barW}
              height={Math.max(0.75, Math.abs(macdZero - y))}
              rx={1}
              fill={positive ? UP : DOWN}
              opacity={hoverIndex != null && hoverIndex !== i ? 0.22 : 0.5}
              style={{
                transition: reduce ? undefined : "opacity 160ms ease-out",
                transformBox: "fill-box",
                transformOrigin: positive ? "bottom center" : "top center",
                animation: reduce
                  ? undefined
                  : `spectrum-mc-rise 420ms ${EASE} ${n <= 1 ? 0 : (i / (n - 1)) * 300}ms both`,
              }}
            />
          );
        })}
        <path d={macdLine} fill="none" stroke="var(--spectrum-chart-1)" strokeWidth={1.5} />
        <path
          d={signalLine}
          fill="none"
          stroke="var(--spectrum-chart-2)"
          strokeWidth={1.5}
          strokeDasharray="4 3"
        />
      </g>
      <PaneLabel x0={x0} y={macdTop - 10} text="MACD 12 · 26 · 9" />
    </>
  );
}

function TimeAxis({
  view,
  timeTicks,
  layout,
  cx,
}: {
  view: Candle[];
  timeTicks: number[];
  layout: Layout;
  cx: Scale;
}) {
  const { x0, x1, innerBottom } = layout;
  return (
    <g className="font-mono">
      {timeTicks.map((i) => {
        const candle = view[i];
        if (!candle) return null;
        return (
          <text
            key={i}
            x={Math.max(x0 + 14, Math.min(x1 - 14, cx(i)))}
            y={innerBottom + 14}
            textAnchor="middle"
            fontSize={10.5}
            fill="currentColor"
            className="tabular-nums"
          >
            {DATE_SHORT.format(candle.t)}
          </text>
        );
      })}
    </g>
  );
}

function HoverOverlay({
  hoverIndex,
  view,
  rsiView,
  macdView,
  layout,
  scales,
  dirColor,
}: {
  hoverIndex: number | null;
  view: Candle[];
  rsiView: (number | null)[];
  macdView: MacdSeries;
  layout: Layout;
  scales: { cx: Scale; priceY: Scale; rsiY: Scale; macdY: Scale };
  dirColor: string;
}) {
  if (hoverIndex == null) return null;
  const candle = view[hoverIndex];
  if (!candle) return null;
  const { x0, x1, priceTop, macdBottom, innerBottom } = layout;
  const { cx, priceY, rsiY, macdY } = scales;
  const rsiValue = rsiView[hoverIndex];
  return (
    <g>
      <line
        x1={cx(hoverIndex)}
        x2={cx(hoverIndex)}
        y1={priceTop}
        y2={macdBottom}
        stroke="currentColor"
        strokeOpacity={0.42}
        strokeDasharray="3 3"
      />
      <circle
        cx={cx(hoverIndex)}
        cy={priceY(candle.close)}
        r={4}
        fill={SURFACE}
        stroke={dirColor}
        strokeWidth={2}
      />
      {rsiValue != null ? (
        <circle
          cx={cx(hoverIndex)}
          cy={rsiY(rsiValue)}
          r={3}
          fill={SURFACE}
          stroke="var(--spectrum-chart-4)"
          strokeWidth={1.75}
        />
      ) : null}
      <circle
        cx={cx(hoverIndex)}
        cy={macdY(macdView.line[hoverIndex]!)}
        r={3}
        fill={SURFACE}
        stroke="var(--spectrum-chart-1)"
        strokeWidth={1.75}
      />
      <g
        transform={`translate(${Math.max(x0 + 28, Math.min(x1 - 28, cx(hoverIndex)))}, ${innerBottom + 4})`}
      >
        <rect x={-27} y={0} width={54} height={16} rx={4} className="fill-foreground" />
        <text
          x={0}
          y={8.5}
          textAnchor="middle"
          dominantBaseline="middle"
          fontSize={10}
          fontWeight={600}
          className="fill-foreground font-mono tabular-nums"
        >
          {DATE_SHORT.format(candle.t)}
        </text>
      </g>
    </g>
  );
}

function IndicatorTable({
  symbol,
  name,
  view,
  rsiView,
  macdView,
}: {
  symbol: string;
  name: string;
  view: Candle[];
  rsiView: (number | null)[];
  macdView: MacdSeries;
}) {
  return (
    <ChartDataTable
      caption={`${symbol} ${name} — close, RSI and MACD by date`}
      columns={["Date", "Close", "RSI", "MACD"]}
      rows={view.map((c, i) => [
        DATE_SHORT.format(c.t),
        formatMoney(c.close),
        fixedOrDash(rsiView[i], 1),
        macdView.line[i]!.toFixed(2),
      ])}
    />
  );
}

export function IndicatorChart({
  className,
  data,
  symbol = "SOL",
  name = "Solana",
  ranges = MARKET_RANGES,
  defaultRange = "3M",
  height = 460,
  status = "ready",
  onRetry,
}: IndicatorChartProps) {
  const reduce = usePrefersReducedMotion();
  const [wrapRef, width] = useElementWidth<HTMLDivElement>();
  const svgRef = React.useRef<SVGSVGElement | null>(null);
  const [rangeLabel, setRangeLabel] = React.useState(
    () => resolveRange(ranges, defaultRange).label,
  );
  const [hoverIndex, setHoverIndex] = React.useState<number | null>(null);

  const { view, rsiView, macdView } = useIndicatorSeries(data, resolveRange(ranges, rangeLabel));
  const n = view.length;
  const layout = indicatorLayout(width, height, n);
  const scales = useIndicatorScales(view, macdView, layout, reduce);
  const paths = useIndicatorPaths(view, rsiView, macdView, scales);
  const { priceTicks, timeTicks } = useIndicatorTicks(
    n,
    layout.plotW,
    scales.pLo,
    scales.pHi,
    scales.cx,
  );

  const onKeyDown = useHoverIndexKeys({ count: n, setIndex: setHoverIndex });
  const onMove = (clientX: number) => {
    const svg = svgRef.current;
    if (!svg) return;
    const box = svg.getBoundingClientRect();
    const x = ((clientX - box.left) / box.width) * layout.w;
    setHoverIndex(Math.max(0, Math.min(n - 1, Math.floor((x - layout.x0) / layout.step))));
  };

  const readout = indicatorReadout(view, rsiView, macdView, hoverIndex);
  const dirColor = dirInk(readout.rangeDelta);
  const uid = React.useId().replace(/:/g, "");
  const ready = width > 0;
  const introKey = rangeLabel;
  const { w, h, x0, plotW, rsiTop, rsiBottom } = layout;

  return (
    <div ref={wrapRef} className={cn("flex w-full flex-col text-muted-foreground/70", className)}>
      <Keyframes />

      <div className="mb-3 flex flex-wrap items-start justify-between gap-x-4 gap-y-3">
        <IndicatorReadout symbol={symbol} name={name} readout={readout} />

        <RangeSelector
          ranges={ranges}
          value={rangeLabel}
          onChange={setRangeLabel}
          reduce={reduce}
        />
      </div>

      <ChartState
        status={status}
        height={height}
        variant="line"
        empty={{
          title: "No price data",
          description: "Indicators need at least 26 candles before MACD can be computed.",
        }}
        onRetry={onRetry}
      >
        <div className="relative w-full" style={{ height }}>
          {!ready ? null : (
            <svg
              ref={svgRef}
              width={w}
              height={h}
              viewBox={`0 0 ${w} ${h}`}
              className="block w-full touch-pan-y select-none overflow-visible"
              role="img"
              aria-label={`${symbol} ${name} with RSI and MACD, ${rangeLabel} range. ${formatMoney(readout.lastClose)}, ${formatSignedPct(readout.rangeDelta)}.`}
              tabIndex={0}
              onKeyDown={onKeyDown}
              onBlur={() => setHoverIndex(null)}
              onPointerMove={(e) => onMove(e.clientX)}
              onPointerDown={(e) => onMove(e.clientX)}
              onPointerLeave={() => setHoverIndex(null)}
            >
              <defs>
                <linearGradient id={`${uid}-price`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor={dirColor} stopOpacity={0.24} />
                  <stop offset="100%" stopColor={dirColor} stopOpacity={0} />
                </linearGradient>
                <clipPath id={`${uid}-rsi`}>
                  <rect x={x0} y={rsiTop} width={plotW} height={Math.max(0, rsiBottom - rsiTop)} />
                </clipPath>
              </defs>

              <PricePane
                symbol={symbol}
                layout={layout}
                n={n}
                cx={scales.cx}
                priceY={scales.priceY}
                priceTicks={priceTicks}
                closeLine={paths.closeLine}
                last={readout.last}
                dirColor={dirColor}
                uid={uid}
                introKey={introKey}
                reduce={reduce}
              />

              <RsiPane
                layout={layout}
                rsiY={scales.rsiY}
                rsiLine={paths.rsiLine}
                uid={uid}
                introKey={introKey}
                reduce={reduce}
              />

              <MacdPane
                layout={layout}
                n={n}
                cx={scales.cx}
                macdY={scales.macdY}
                histogram={macdView.histogram}
                macdLine={paths.macdLine}
                signalLine={paths.signalLine}
                hoverIndex={hoverIndex}
                introKey={introKey}
                reduce={reduce}
              />

              <TimeAxis view={view} timeTicks={timeTicks} layout={layout} cx={scales.cx} />

              <HoverOverlay
                hoverIndex={hoverIndex}
                view={view}
                rsiView={rsiView}
                macdView={macdView}
                layout={layout}
                scales={scales}
                dirColor={dirColor}
              />
            </svg>
          )}
        </div>
      </ChartState>
      <IndicatorTable
        symbol={symbol}
        name={name}
        view={view}
        rsiView={rsiView}
        macdView={macdView}
      />
    </div>
  );
}
